// Converte o retorno bruto da API do Google Sheets em array de objetos
const sheetData = $json.values;
if (!sheetData || sheetData.length < 2) return [];

const headers = sheetData[0];
const results = [];

for (let i = 1; i < sheetData.length; i++) {
  const row = sheetData[i];
  if (!row || row.length === 0) continue;

  const obj = {};
  headers.forEach((header, idx) => {
    obj[header] = row[idx] !== undefined ? row[idx] : '';
  });

  results.push({ json: obj });
}

return results;

const MAPA_EMAILS = {
  'Rodrigo Bertolini': 'rodrigo.bertolini@fazcapital.com.br',
  'Lucas Boeira': 'lucas.boeira@fazcapital.com.br',
  'Allini Pianca': 'allini.pianca@fazcapital.com.br',
  'Athos Baruk': 'athos.baruk@fazcapital.com.br',
  'Fabio Borges': 'fabio.borges@fazcapital.com.br'
};

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json;
  const status = (d['Status'] || '').trim();
  const statusLower = status.toLowerCase();
  const ultimoEnviado = (d['Ultimo Status Enviado'] || '').trim().toLowerCase();

  if (statusLower === ultimoEnviado || statusLower === 'aberto') continue;

  const responsavel = (d['Responsável'] || '').split('|')[0].trim();
  const emailDest = MAPA_EMAILS[responsavel] || '';
  if (!emailDest) continue;

  const idCaso   = d['ID Caso'] || '';
  const cliente  = d['Código Cliente'] || '';
  const assunto  = d['Assunto'] || '';
  const proto    = d['Protocolo N1'] || '';
  const threadId = d['Thread ID'] || '';

  const subjectLine = `Re: [SUBIR BV] ${idCaso} | Cliente ${cliente} | ${assunto}`;

  let corpo = '';

  if (statusLower === 'em análise') {
    corpo = `<p>Prezado(a),</p><p>Informamos que o caso <strong>${idCaso}</strong> está agora <strong>Em Análise</strong> pela nossa equipe. 🔍</p><p>📌 Protocolo: ${proto}<br>👤 Cliente: ${cliente}<br>📝 Assunto: ${assunto}</p><p>Estamos trabalhando na resolução e em breve traremos novidades. Caso possua novas informações, responda este e-mail.</p><br><p>Atenciosamente,</p>`;
  } else if (statusLower === 'resolvido') {
    corpo = `<p>Prezado(a),</p><p>Informamos que o caso <strong>${idCaso}</strong> foi <strong>Resolvido</strong>! ✅</p><p>📌 Protocolo: ${proto}<br>👤 Cliente: ${cliente}<br>📝 Assunto: ${assunto}</p><p>Caso o problema persista ou tenha novas dúvidas, responda este e-mail para reabrir o caso.</p><br><p>Atenciosamente,</p>`;
  } else if (statusLower === 'aguardando retorno') {
    corpo = `<p>Prezado(a),</p><p>O caso <strong>${idCaso}</strong> está <strong>Aguardando o seu Retorno</strong>. ⏳</p><p>📌 Protocolo: ${proto}<br>👤 Cliente: ${cliente}<br>📝 Assunto: ${assunto}</p><p>Por favor, responda este e-mail com as informações solicitadas para prosseguirmos com o atendimento.</p><br><p>Atenciosamente,</p>`;
  }

  if (!corpo) continue;

  results.push({
    json: {
      ...d,
      corpo_email: corpo,
      email_destinatario: emailDest,
      assunto_email: subjectLine,
      request_body: {
        message: {
          subject: subjectLine,
          body: {
            contentType: 'HTML',
            content: corpo
          },
          toRecipients: [
            { emailAddress: { address: emailDest } }
          ],
          ccRecipients: [
            { emailAddress: { address: 'lucas.boeira@fazcapital.com.br' } }
          ],
          internetMessageHeaders: [
            { name: 'In-Reply-To', value: threadId },
            { name: 'References', value: threadId }
          ]
        }
      }
    }
  });
}

return results;
